<?php
declare(strict_types=1);

function admin_woocommerce_home(): void {
    $period=(int)($_GET['period'] ?? 30); if(!in_array($period,[7,30,90],true)) $period=30;
    $orders=(int)(row("SELECT COUNT(*) n FROM wp_posts WHERE post_type='shop_order' AND post_status NOT IN ('trash','auto-draft')")['n'] ?? 0);
    $products=(int)(row("SELECT COUNT(*) n FROM wp_posts WHERE post_type='product' AND post_status='publish'")['n'] ?? 0);
    $customers=(int)(row("SELECT COUNT(DISTINCT u.ID) n FROM wp_users u JOIN wp_usermeta m ON m.user_id=u.ID AND m.meta_key='wp_capabilities' WHERE m.meta_value LIKE '%customer%' OR m.meta_value LIKE '%wholesale%'")['n'] ?? 0);
    $pending=(int)(row("SELECT COUNT(*) n FROM wp_posts WHERE post_type='shop_order' AND post_status IN ('wc-pending','wc-on-hold','wc-processing')")['n'] ?? 0);
    $valid="p.post_type='shop_order' AND p.post_status NOT IN ('trash','auto-draft','wc-cancelled','wc-failed','wc-refunded')";
    $totals="LEFT JOIN wp_postmeta ot ON ot.post_id=p.ID AND ot.meta_key='_order_total'";
    $summary=row("SELECT COUNT(DISTINCT CASE WHEN p.post_date>=DATE_SUB(NOW(),INTERVAL $period DAY) THEN p.ID END) period_orders,COALESCE(SUM(CASE WHEN p.post_date>=DATE_SUB(NOW(),INTERVAL $period DAY) THEN CAST(ot.meta_value AS DECIMAL(18,2)) ELSE 0 END),0) period_revenue,COUNT(DISTINCT CASE WHEN p.post_date<DATE_SUB(NOW(),INTERVAL $period DAY) THEN p.ID END) prior_orders,COALESCE(SUM(CASE WHEN p.post_date<DATE_SUB(NOW(),INTERVAL $period DAY) THEN CAST(ot.meta_value AS DECIMAL(18,2)) ELSE 0 END),0) prior_revenue FROM wp_posts p $totals WHERE $valid AND p.post_date>=DATE_SUB(NOW(),INTERVAL ".($period*2)." DAY)") ?: [];
    $periodOrders=(int)($summary['period_orders'] ?? 0); $periodRevenue=(float)($summary['period_revenue'] ?? 0); $priorOrders=(int)($summary['prior_orders'] ?? 0); $priorRevenue=(float)($summary['prior_revenue'] ?? 0);
    $orderChange=$priorOrders>0?(($periodOrders-$priorOrders)/$priorOrders)*100:null; $revenueChange=$priorRevenue>0?(($periodRevenue-$priorRevenue)/$priorRevenue)*100:null; $average=$periodOrders>0?$periodRevenue/$periodOrders:0;
    $dailyRows=rows("SELECT DATE(p.post_date) day,COUNT(DISTINCT p.ID) orders,COALESCE(SUM(CAST(ot.meta_value AS DECIMAL(18,2))),0) revenue FROM wp_posts p $totals WHERE $valid AND p.post_date>=DATE_SUB(CURDATE(),INTERVAL ".($period-1)." DAY) GROUP BY DATE(p.post_date) ORDER BY day");
    $dailyMap=[]; foreach($dailyRows as $entry) $dailyMap[$entry['day']]=['orders'=>(int)$entry['orders'],'revenue'=>(float)$entry['revenue']];
    $daily=[]; $start=(new DateTimeImmutable('today'))->modify('-'.($period-1).' days'); for($i=0;$i<$period;$i++){ $date=$start->modify('+'.$i.' days'); $key=$date->format('Y-m-d'); $daily[]=['day'=>$key,'label'=>$date->format($period===7?'D':'j M'),'orders'=>$dailyMap[$key]['orders'] ?? 0,'revenue'=>$dailyMap[$key]['revenue'] ?? 0.0]; }
    $maxRevenue=max(1.0,...array_column($daily,'revenue')); $maxOrders=max(1,...array_column($daily,'orders')); $chartWidth=760; $chartHeight=214; $plotTop=18; $plotBottom=184; $step=count($daily)>1?$chartWidth/(count($daily)-1):$chartWidth; $revenuePoints=[]; $orderPoints=[];
    foreach($daily as $i=>$entry){$x=$i*$step;$revenueY=$plotBottom-($entry['revenue']/$maxRevenue)*($plotBottom-$plotTop);$orderY=$plotBottom-($entry['orders']/$maxOrders)*($plotBottom-$plotTop);$revenuePoints[]=round($x,2).','.round($revenueY,2);$orderPoints[]=round($x,2).','.round($orderY,2);}
    $areaPoints='0,'.$plotBottom.' '.implode(' ',$revenuePoints).' '.$chartWidth.','.$plotBottom;
    $recent=rows("SELECT p.ID,p.post_date,p.post_status,(SELECT m.meta_value FROM wp_postmeta m WHERE m.post_id=p.ID AND m.meta_key='_order_total' ORDER BY m.meta_id DESC LIMIT 1) total,(SELECT m.meta_value FROM wp_postmeta m WHERE m.post_id=p.ID AND m.meta_key='_billing_email' ORDER BY m.meta_id DESC LIMIT 1) email FROM wp_posts p WHERE p.post_type='shop_order' ORDER BY p.post_date DESC,p.ID DESC LIMIT 7");
    $statuses=rows("SELECT post_status,COUNT(*) n FROM wp_posts WHERE post_type='shop_order' GROUP BY post_status ORDER BY n DESC");
    $topProducts=rows("SELECT oi.order_item_name name,SUM(CAST(q.meta_value AS UNSIGNED)) units,COALESCE(SUM(CAST(line.meta_value AS DECIMAL(18,2))),0) revenue FROM wp_woocommerce_order_items oi JOIN wp_posts p ON p.ID=oi.order_id LEFT JOIN wp_woocommerce_order_itemmeta q ON q.order_item_id=oi.order_item_id AND q.meta_key='_qty' LEFT JOIN wp_woocommerce_order_itemmeta line ON line.order_item_id=oi.order_item_id AND line.meta_key='_line_total' WHERE oi.order_item_type='line_item' AND $valid AND p.post_date>=DATE_SUB(NOW(),INTERVAL $period DAY) GROUP BY oi.order_item_name ORDER BY revenue DESC,units DESC LIMIT 6");
    $inventory=row("SELECT SUM(CASE WHEN COALESCE(stock.meta_value+0,0)<=5 AND status.meta_value='instock' THEN 1 ELSE 0 END) low_stock,SUM(CASE WHEN status.meta_value='outofstock' THEN 1 ELSE 0 END) out_stock FROM wp_posts p LEFT JOIN wp_postmeta stock ON stock.post_id=p.ID AND stock.meta_key='_stock' LEFT JOIN wp_postmeta status ON status.post_id=p.ID AND status.meta_key='_stock_status' WHERE p.post_type='product' AND p.post_status='publish'") ?: [];
    $newCustomers=(int)(row("SELECT COUNT(*) n FROM wp_users WHERE user_registered>=DATE_SUB(NOW(),INTERVAL $period DAY)")['n'] ?? 0);
    $statusTotal=max(1,array_sum(array_map(static fn($s)=>(int)$s['n'],$statuses)));
    admin_layout('Commerce overview',static function() use($period,$orders,$products,$customers,$pending,$periodOrders,$periodRevenue,$average,$orderChange,$revenueChange,$daily,$revenuePoints,$orderPoints,$areaPoints,$chartWidth,$chartHeight,$recent,$statuses,$statusTotal,$topProducts,$inventory,$newCustomers){
      $change=static function(?float $value): string { if($value===null)return '<span class="commerce-change is-neutral">No prior data</span>'; $class=$value>=0?'is-up':'is-down'; return '<span class="commerce-change '.$class.'">'.($value>=0?'↗ ':'↘ ').number_format(abs($value),1).'% vs prior period</span>'; }; ?>
      <div class="commerce-head"><div><div class="eyebrow">STORE INTELLIGENCE</div><h1>Commerce overview</h1><p>Orders, revenue, customers and inventory in one live workspace.</p></div><div class="commerce-head__actions"><nav class="commerce-period" aria-label="Report period"><?php foreach([7,30,90] as $days): ?><a class="<?=$period===$days?'active':''?>" href="<?=h(path('/admin/woocommerce?period='.$days))?>"><?=$days?> days</a><?php endforeach; ?></nav><a class="commerce-primary" href="<?=h(path('/admin/orders'))?>">View orders <span>→</span></a></div></div>
      <div class="commerce-metrics">
        <a href="<?=h(path('/admin/orders'))?>"><span class="commerce-metric__icon is-blue">↗</span><div><small>Net revenue</small><strong><?=currency($periodRevenue)?></strong><?=$change($revenueChange)?></div></a>
        <a href="<?=h(path('/admin/orders'))?>"><span class="commerce-metric__icon is-violet">□</span><div><small>Orders</small><strong><?=number_format($periodOrders)?></strong><?=$change($orderChange)?></div></a>
        <a href="<?=h(path('/admin/orders'))?>"><span class="commerce-metric__icon is-amber">◎</span><div><small>Average order</small><strong><?=currency($average)?></strong><span class="commerce-change is-neutral"><?=number_format($pending)?> need attention</span></div></a>
        <a href="<?=h(path('/admin/users'))?>"><span class="commerce-metric__icon is-green">+</span><div><small>New customers</small><strong><?=number_format($newCustomers)?></strong><span class="commerce-change is-neutral"><?=number_format($customers)?> total accounts</span></div></a>
      </div>
      <div class="commerce-grid commerce-grid--hero"><section class="commerce-card commerce-chart-card"><div class="commerce-card__head"><div><span>PERFORMANCE</span><h2>Revenue and orders</h2></div><div class="commerce-legend"><i class="revenue"></i>Revenue <i class="orders"></i>Orders</div></div><div class="commerce-chart" role="img" aria-label="Revenue and order trend for the last <?=$period?> days"><div class="commerce-chart__scale"><span><?=currency(max(array_column($daily,'revenue')))?></span><span><?=currency(max(array_column($daily,'revenue'))/2)?></span><span>CHF 0.00</span></div><svg viewBox="0 0 <?=$chartWidth?> <?=$chartHeight?>" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="commerceArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#2878f0" stop-opacity=".24"/><stop offset="1" stop-color="#2878f0" stop-opacity="0"/></linearGradient></defs><path class="commerce-grid-line" d="M0 18H760M0 101H760M0 184H760"/><polygon points="<?=h($areaPoints)?>" fill="url(#commerceArea)"/><polyline class="commerce-line commerce-line--revenue" points="<?=h(implode(' ',$revenuePoints))?>"/><polyline class="commerce-line commerce-line--orders" points="<?=h(implode(' ',$orderPoints))?>"/><?php foreach($daily as $i=>$entry): $x=count($daily)>1?$i*($chartWidth/(count($daily)-1)):0; ?><circle class="commerce-dot" cx="<?=round($x,2)?>" cy="<?=round(184-($entry['revenue']/max(1,max(array_column($daily,'revenue'))))*166,2)?>" r="2"><title><?=h($entry['label'])?>: <?=h(currency($entry['revenue']))?> · <?=number_format($entry['orders'])?> orders</title></circle><?php endforeach; ?></svg><div class="commerce-chart__labels"><span><?=h($daily[0]['label'])?></span><span><?=h($daily[(int)floor((count($daily)-1)/2)]['label'])?></span><span><?=h($daily[count($daily)-1]['label'])?></span></div></div></section>
        <section class="commerce-card"><div class="commerce-card__head"><div><span>FULFILMENT</span><h2>Order status</h2></div><a href="<?=h(path('/admin/orders'))?>">All orders</a></div><div class="commerce-statuses"><?php foreach(array_slice($statuses,0,7) as $s): $label=ucwords(str_replace(['wc-','-'],['',' '],$s['post_status']));$percent=((int)$s['n']/$statusTotal)*100; ?><a href="<?=h(path('/admin/orders?status='.rawurlencode($s['post_status'])))?>"><div><span><?=h($label)?></span><strong><?=number_format((int)$s['n'])?></strong></div><i><b style="width:<?=round($percent,1)?>%"></b></i></a><?php endforeach; ?></div></section></div>
      <div class="commerce-grid commerce-grid--lower"><section class="commerce-card"><div class="commerce-card__head"><div><span>SALES</span><h2>Top products</h2></div><a href="<?=h(path('/admin/products'))?>">Catalogue</a></div><div class="commerce-products"><?php foreach($topProducts as $index=>$product): ?><div><span class="commerce-rank"><?=str_pad((string)($index+1),2,'0',STR_PAD_LEFT)?></span><p><strong><?=h($product['name'])?></strong><small><?=number_format((int)$product['units'])?> units sold</small></p><b><?=currency($product['revenue'])?></b></div><?php endforeach; if(!$topProducts): ?><p class="commerce-empty">No product sales in this period.</p><?php endif; ?></div></section>
        <section class="commerce-card"><div class="commerce-card__head"><div><span>ACTIVITY</span><h2>Recent orders</h2></div><a href="<?=h(path('/admin/orders'))?>">Open list</a></div><div class="commerce-orders"><?php foreach($recent as $o): ?><a href="<?=h(path('/admin/order?id='.$o['ID']))?>"><span class="commerce-order-id">#<?=h($o['ID'])?></span><p><strong><?=h($o['email'] ?: 'Guest customer')?></strong><small><?=h(date('j M Y, H:i',strtotime($o['post_date'])))?></small></p><em><?=h(ucwords(str_replace(['wc-','-'],['',' '],$o['post_status'])))?></em><b><?=currency($o['total'] ?? 0)?></b></a><?php endforeach; if(!$recent): ?><p class="commerce-empty">No orders found.</p><?php endif; ?></div></section>
        <aside class="commerce-card commerce-health"><div class="commerce-card__head"><div><span>STORE HEALTH</span><h2>At a glance</h2></div></div><a href="<?=h(path('/admin/orders'))?>"><span>Orders to handle</span><strong><?=number_format($pending)?></strong></a><a href="<?=h(path('/admin/products?stock=instock'))?>"><span>Low stock</span><strong><?=number_format((int)($inventory['low_stock'] ?? 0))?></strong></a><a href="<?=h(path('/admin/products?stock=outofstock'))?>"><span>Out of stock</span><strong><?=number_format((int)($inventory['out_stock'] ?? 0))?></strong></a><a href="<?=h(path('/admin/products'))?>"><span>Published products</span><strong><?=number_format($products)?></strong></a><a href="<?=h(path('/admin/users'))?>"><span>Customer accounts</span><strong><?=number_format($customers)?></strong></a><div class="commerce-shortcuts"><a href="<?=h(path('/admin/coupons'))?>">Coupons</a><a href="<?=h(path('/admin/shipments'))?>">Shipments</a><a href="<?=h(path('/admin/woocommerce/settings'))?>">Settings</a></div></aside></div>
      <link rel="stylesheet" href="<?=h(path('/assets/woocommerce-admin.css?v=2'))?>"><?php });
}

function admin_woo_coupons(): void {
    $q=trim((string)($_GET['q'] ?? '')); $status=(string)($_GET['status'] ?? '');
    if(!in_array($status,['','publish','draft','trash'],true)) $status='';
    $page=max(1,(int)($_GET['page'] ?? 1)); $limit=30; $offset=($page-1)*$limit;
    $where="p.post_type='shop_coupon'"; $params=[];
    if($status!=='') { $where.=' AND p.post_status=?'; $params[]=$status; }
    else $where.=" AND p.post_status<>'trash'";
    if($q!=='') { $where.=' AND p.post_title LIKE ?'; $params[]='%'.$q.'%'; }
    $count=(int)(row("SELECT COUNT(*) n FROM wp_posts p WHERE $where",$params)['n'] ?? 0);
    $items=rows("SELECT p.ID,p.post_title,p.post_status,p.post_date,(SELECT m.meta_value FROM wp_postmeta m WHERE m.post_id=p.ID AND m.meta_key='discount_type' ORDER BY m.meta_id DESC LIMIT 1) discount_type,(SELECT m.meta_value FROM wp_postmeta m WHERE m.post_id=p.ID AND m.meta_key='coupon_amount' ORDER BY m.meta_id DESC LIMIT 1) amount,(SELECT m.meta_value FROM wp_postmeta m WHERE m.post_id=p.ID AND m.meta_key='usage_count' ORDER BY m.meta_id DESC LIMIT 1) usage_count,(SELECT m.meta_value FROM wp_postmeta m WHERE m.post_id=p.ID AND m.meta_key='usage_limit' ORDER BY m.meta_id DESC LIMIT 1) usage_limit FROM wp_posts p WHERE $where ORDER BY p.ID DESC LIMIT $limit OFFSET $offset",$params);
    $totals=rows("SELECT post_status,COUNT(*) n FROM wp_posts WHERE post_type='shop_coupon' GROUP BY post_status");
    admin_layout('Coupons',static function() use($items,$totals,$q,$status,$count,$page,$limit){ ?><div class="wp-posts-list"><div class="wp-list-top"><div class="wp-list-title"><h1>Coupons</h1><a class="secondary" href="<?=h(path('/admin/coupon/new'))?>">Add coupon</a></div><details class="wp-list-screen"><summary aria-label="Screen Options" title="Screen Options">☷</summary><div class="wp-list-screen-panel"><strong>Pagination</strong><span>30 coupons per page</span></div></details></div><nav class="wp-status-links" aria-label="Coupon statuses"><a class="<?=$status===''?'current':''?>" href="<?=h(path('/admin/coupons'))?>">All</a><?php foreach($totals as $t): ?><a class="<?=$status===$t['post_status']?'current':''?>" href="<?=h(path('/admin/coupons?status='.rawurlencode($t['post_status'])))?>"><?=h(ucfirst($t['post_status']))?> (<?=h($t['n'])?>)</a><?php endforeach; ?></nav><form action="<?=h(path('/admin/coupons'))?>" class="wp-list-search"><input type="hidden" name="status" value="<?=h($status)?>"><input name="q" value="<?=h($q)?>" placeholder="Search coupons" aria-label="Search coupons"><button class="secondary">Search Coupons</button></form><div class="wp-list-actions"><span><?=number_format($count)?> <?=$count===1?'item':'items'?></span></div><div class="wp-list-table-wrap"><table class="wp-list-table"><thead><tr><th>Code</th><th>Type</th><th>Amount</th><th>Usage / Limit</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($items as $c): ?><tr><td><strong><a href="<?=h(path('/admin/coupon?id='.$c['ID']))?>"><?=h($c['post_title'])?></a></strong></td><td><?=h(str_replace('_',' ',(string)$c['discount_type']))?></td><td><?=h($c['amount'])?></td><td><?=h($c['usage_count'] ?? 0)?> / <?=h($c['usage_limit'] ?: '∞')?></td><td><?=h($c['post_status'])?></td><td><?=h($c['post_date'])?></td></tr><?php endforeach; if(!$items): ?><tr><td colspan="6">No coupons found.</td></tr><?php endif; ?></tbody></table></div><?=admin_pages_nav('/admin/coupons',$page,$count,$limit,['q'=>$q,'status'=>$status])?></div><link rel="stylesheet" href="<?=h(path('/assets/posts-list.css'))?>"><?php });
}

function admin_woo_coupon(int $id=0): void {
    $coupon=$id?row("SELECT ID,post_title,post_status FROM wp_posts WHERE ID=? AND post_type='shop_coupon'",[$id]):null;
    if($id && !$coupon) { http_response_code(404); exit('Coupon not found.'); }
    $meta=[];
    if($id) foreach(rows("SELECT meta_key,meta_value FROM wp_postmeta WHERE post_id=? AND meta_key IN ('discount_type','coupon_amount','individual_use','product_ids','exclude_product_ids','usage_limit','usage_limit_per_user','date_expires','minimum_amount','maximum_amount','free_shipping') ORDER BY meta_id",[$id]) as $item) $meta[$item['meta_key']]=$item['meta_value'];
    admin_layout($id?'Edit coupon':'Add coupon',static function() use($coupon,$meta,$id){ ?><div class="heading"><div><div class="eyebrow">COMMERCE</div><h1><?=$id?'Edit coupon':'Add coupon'?></h1></div><a class="secondary" href="<?=h(path('/admin/coupons'))?>">Back to coupons</a></div><form class="panel edit-form woo-coupon-form" method="post" action="<?=h(path('/admin/coupon'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Coupon code<input name="code" value="<?=h($coupon['post_title'] ?? '')?>" maxlength="200" required autocomplete="off"></label><div class="woo-form-grid"><label>Discount type<select name="discount_type"><option value="percent" <?=($meta['discount_type'] ?? '')==='percent'?'selected':''?>>Percentage discount</option><option value="fixed_cart" <?=($meta['discount_type'] ?? '')==='fixed_cart'?'selected':''?>>Fixed cart discount</option><option value="fixed_product" <?=($meta['discount_type'] ?? '')==='fixed_product'?'selected':''?>>Fixed product discount</option></select></label><label>Coupon amount<input type="number" min="0" step="0.01" name="amount" value="<?=h($meta['coupon_amount'] ?? '0')?>" required></label><label>Usage limit<input type="number" min="0" name="usage_limit" value="<?=h($meta['usage_limit'] ?? '')?>" placeholder="Unlimited"></label><label>Usage limit per user<input type="number" min="0" name="usage_limit_per_user" value="<?=h($meta['usage_limit_per_user'] ?? '')?>" placeholder="Unlimited"></label><label>Minimum spend<input type="number" min="0" step="0.01" name="minimum_amount" value="<?=h($meta['minimum_amount'] ?? '')?>"></label><label>Maximum spend<input type="number" min="0" step="0.01" name="maximum_amount" value="<?=h($meta['maximum_amount'] ?? '')?>"></label></div><label>Product IDs <small>Comma separated</small><input name="product_ids" value="<?=h($meta['product_ids'] ?? '')?>"></label><label>Exclude product IDs <small>Comma separated</small><input name="exclude_product_ids" value="<?=h($meta['exclude_product_ids'] ?? '')?>"></label><label class="woo-check"><input type="checkbox" name="individual_use" value="yes" <?=($meta['individual_use'] ?? '')==='yes'?'checked':''?>> Individual use only</label><label class="woo-check"><input type="checkbox" name="free_shipping" value="yes" <?=($meta['free_shipping'] ?? '')==='yes'?'checked':''?>> Allow free shipping</label><label>Status<select name="status"><option value="publish" <?=($coupon['post_status'] ?? 'publish')==='publish'?'selected':''?>>Published</option><option value="draft" <?=($coupon['post_status'] ?? '')==='draft'?'selected':''?>>Draft</option><option value="trash" <?=($coupon['post_status'] ?? '')==='trash'?'selected':''?>>Trash</option></select></label><button class="primary">Save coupon</button></form><link rel="stylesheet" href="<?=h(path('/assets/woocommerce-admin.css?v=2'))?>"><?php });
}

function save_woo_coupon(): never {
    $id=(int)($_POST['id'] ?? 0); $code=strtolower(trim((string)($_POST['code'] ?? ''))); $type=(string)($_POST['discount_type'] ?? ''); $status=(string)($_POST['status'] ?? '');
    if(!preg_match('/^[a-z0-9][a-z0-9_-]{1,199}$/',$code) || !in_array($type,['percent','fixed_cart','fixed_product'],true) || !in_array($status,['publish','draft','trash'],true)) { notice('Check the coupon code, type and status.'); redirect($id?'/admin/coupon?id='.$id:'/admin/coupon/new'); }
    $amount=filter_var($_POST['amount'] ?? '',FILTER_VALIDATE_FLOAT);
    if($amount===false || $amount<0 || ($type==='percent' && $amount>100)) { notice('Enter a valid coupon amount.'); redirect($id?'/admin/coupon?id='.$id:'/admin/coupon/new'); }
    $before=$id?row("SELECT ID,post_title,post_status FROM wp_posts WHERE ID=? AND post_type='shop_coupon'",[$id]):null;
    if($id && !$before) { http_response_code(404); exit('Coupon not found.'); }
    $duplicate=row("SELECT ID FROM wp_posts WHERE post_type='shop_coupon' AND post_title=? AND ID<>? LIMIT 1",[$code,$id]);
    if($duplicate) { notice('That coupon code already exists.'); redirect($id?'/admin/coupon?id='.$id:'/admin/coupon/new'); }
    $fields=['discount_type'=>$type,'coupon_amount'=>(string)$amount,'individual_use'=>isset($_POST['individual_use'])?'yes':'no','free_shipping'=>isset($_POST['free_shipping'])?'yes':'no'];
    foreach(['usage_limit','usage_limit_per_user'] as $key) { $value=trim((string)($_POST[$key] ?? '')); if($value!=='' && (!ctype_digit($value) || (int)$value<0)) { notice('Enter a valid usage limit.'); redirect($id?'/admin/coupon?id='.$id:'/admin/coupon/new'); } $fields[$key]=$value; }
    foreach(['minimum_amount','maximum_amount'] as $key) { $value=trim((string)($_POST[$key] ?? '')); if($value!=='' && (!is_numeric($value) || (float)$value<0)) { notice('Enter a valid spend amount.'); redirect($id?'/admin/coupon?id='.$id:'/admin/coupon/new'); } $fields[$key]=$value; }
    foreach(['product_ids','exclude_product_ids'] as $key) { $value=trim((string)($_POST[$key] ?? '')); if($value!=='' && !preg_match('/^\d+(\s*,\s*\d+)*$/',$value)) { notice('Product IDs must be comma separated numbers.'); redirect($id?'/admin/coupon?id='.$id:'/admin/coupon/new'); } $fields[$key]=preg_replace('/\s+/','',$value); }
    db()->beginTransaction();
    try {
        if($before) exec_sql("UPDATE wp_posts SET post_title=?,post_name=?,post_status=?,post_modified=NOW(),post_modified_gmt=UTC_TIMESTAMP() WHERE ID=? AND post_type='shop_coupon'",[$code,$code,$status,$id]);
        else { exec_sql("INSERT INTO wp_posts (post_author,post_date,post_date_gmt,post_content,post_title,post_excerpt,post_status,comment_status,ping_status,post_name,to_ping,pinged,post_modified,post_modified_gmt,post_content_filtered,post_parent,guid,menu_order,post_type,post_mime_type,comment_count) VALUES (?,NOW(),UTC_TIMESTAMP(),'',?,'',?,'closed','closed',?,'','',NOW(),UTC_TIMESTAMP(),'',0,'',0,'shop_coupon','',0)",[(int)(current_user()['id'] ?? 0),$code,$status,$code]); $id=(int)db()->lastInsertId(); }
        foreach($fields as $key=>$value) set_wp_meta($id,$key,$value);
        audit_change('coupon',$id,$before?'update':'create',$before ?? [],['code'=>$code,'status'=>$status,'fields'=>$fields]);
        db()->commit();
    } catch(Throwable $e) { db()->rollBack(); throw $e; }
    woo_webhook_after_change($before?'coupon.updated':'coupon.created',$id);
    notice('Coupon saved.'); redirect('/admin/coupon?id='.$id);
}

function admin_woo_settings(): void {
    $names=['woocommerce_store_address','woocommerce_store_address_2','woocommerce_store_city','woocommerce_store_postcode','woocommerce_default_country','woocommerce_currency','woocommerce_price_num_decimals','woocommerce_price_decimal_sep','woocommerce_price_thousand_sep','woocommerce_calc_taxes','woocommerce_enable_coupons'];
