function save_woo_settings(): never {
    $keys=['woocommerce_store_address','woocommerce_store_address_2','woocommerce_store_city','woocommerce_store_postcode','woocommerce_default_country','woocommerce_currency','woocommerce_price_num_decimals','woocommerce_price_decimal_sep','woocommerce_price_thousand_sep'];
    $values=[]; foreach($keys as $key) $values[$key]=trim((string)($_POST[$key] ?? ''));
    $values['woocommerce_currency']=strtoupper($values['woocommerce_currency']);
    if(!preg_match('/^[A-Z]{3}$/',$values['woocommerce_currency']) || !preg_match('/^[0-6]$/',$values['woocommerce_price_num_decimals']) || strlen($values['woocommerce_price_decimal_sep'])!==1 || strlen($values['woocommerce_price_thousand_sep'])>1) { notice('Check the currency and price format.'); redirect('/admin/woocommerce/settings'); }
    foreach($keys as $key) if(mb_strlen($values[$key])>190) { notice('A setting is too long.'); redirect('/admin/woocommerce/settings'); }
    foreach(['woocommerce_calc_taxes','woocommerce_enable_coupons'] as $key) $values[$key]=isset($_POST[$key])?'yes':'no';
    db()->beginTransaction();
    try { foreach($values as $key=>$value) { $old=row('SELECT option_id,option_value FROM wp_options WHERE option_name=? FOR UPDATE',[$key]); if($old) exec_sql('UPDATE wp_options SET option_value=? WHERE option_id=?',[$value,$old['option_id']]); else exec_sql("INSERT INTO wp_options (option_name,option_value,autoload) VALUES (?,?,'yes')",[$key,$value]); } audit_change('woocommerce_settings',0,'update',[],array_keys($values)); db()->commit(); }
    catch(Throwable $e) { db()->rollBack(); throw $e; }
    notice('Store settings saved.'); redirect('/admin/woocommerce/settings');
}

