    if($origin!=='') { $where.=" AND EXISTS (SELECT 1 FROM wp_postmeta m WHERE m.post_id=p.ID AND m.meta_key='_created_via' AND m.meta_value=?)"; $params[]=$origin; }
    if($q!=='') { $where.=" AND (p.ID=? OR EXISTS (SELECT 1 FROM wp_postmeta m WHERE m.post_id=p.ID AND m.meta_key IN ('_billing_email','_billing_first_name','_billing_last_name','_billing_company') AND m.meta_value LIKE ?))"; $params[]=(int)ltrim($q,'#'); $params[]='%'.$q.'%'; }
    $count=(int)(row("SELECT COUNT(*) n FROM wp_posts p WHERE $where",$params)['n'] ?? 0);
    $meta=static fn(string $key): string=>"(SELECT m.meta_value FROM wp_postmeta m WHERE m.post_id=p.ID AND m.meta_key='".$key."' ORDER BY m.meta_id DESC LIMIT 1)";
    $fields=['_order_total'=>'total','_billing_first_name'=>'first_name','_billing_last_name'=>'last_name','_billing_company'=>'company','_billing_email'=>'email','_billing_address_1'=>'billing_address','_billing_city'=>'billing_city','_shipping_first_name'=>'shipping_first','_shipping_last_name'=>'shipping_last','_shipping_company'=>'shipping_company','_shipping_address_1'=>'shipping_address','_shipping_city'=>'shipping_city','_wcpdf_invoice_number'=>'invoice_number','_wwpp_wholesale_order_type'=>'order_type','_created_via'=>'origin','_wc_shipment_tracking_items'=>'tracking'];
    $columns=[]; foreach($fields as $key=>$alias) $columns[]=$meta($key).' '.$alias;
    $orders=rows('SELECT p.ID,p.post_date,p.post_status,'.implode(',',$columns)." FROM wp_posts p WHERE $where ORDER BY p.post_date DESC,p.ID DESC LIMIT $limit OFFSET $offset",$params);
    $statuses=rows("SELECT post_status,COUNT(*) n FROM wp_posts WHERE post_type='shop_order' AND post_status<>'trash' GROUP BY post_status ORDER BY n DESC");
    $months=rows("SELECT DATE_FORMAT(post_date,'%Y%m') value,DATE_FORMAT(post_date,'%M %Y') label FROM wp_posts WHERE post_type='shop_order' GROUP BY value,label ORDER BY value DESC LIMIT 48");
