      <nav class="wp-status-links" aria-label="Order statuses"><a class="<?=$status===''?'active':''?>" href="<?=h(path('/admin/orders'))?>">All</a><?php foreach($statuses as $s): ?><a class="<?=$status===$s['post_status']?'active':''?>" href="<?=h(path('/admin/orders?status='.rawurlencode($s['post_status'])))?>"><?=h(ucwords(str_replace(['wc-','-'],['',' '],$s['post_status'])))?> (<?=number_format((int)$s['n'])?>)</a><?php endforeach; ?></nav>
      <form class="wp-list-filter" action="<?=h(path('/admin/orders'))?>"><input type="hidden" name="status" value="<?=h($status)?>"><div class="wp-list-search"><label class="sr-only" for="order-search">Search orders</label><input id="order-search" name="q" value="<?=h($q)?>" placeholder="Search orders"><button class="secondary">Search orders</button></div><div class="wp-list-actions"><label class="sr-only" for="order-month">Filter by date</label><select id="order-month" name="month"><option value="">All dates</option><?php foreach($months as $m): ?><option value="<?=h($m['value'])?>" <?=$month===$m['value']?'selected':''?>><?=h($m['label'])?></option><?php endforeach; ?></select><label class="sr-only" for="order-role">Order type</label><select id="order-role" name="role"><option value="">Show all order types</option><?php foreach($roles as $r): ?><option value="<?=h($r['slug'])?>" <?=$role===$r['slug']?'selected':''?>><?=h($r['name'])?></option><?php endforeach; ?></select><label class="sr-only" for="order-origin">Sales channel</label><select id="order-origin" name="origin"><option value="">All sales channels</option><?php foreach(['admin'=>'Admin','checkout'=>'Checkout','store-api'=>'Store API'] as $value=>$label): ?><option value="<?=h($value)?>" <?=$origin===$value?'selected':''?>><?=h($label)?></option><?php endforeach; ?></select><button class="secondary">Filter</button></div></form>
      <form method="post" action="<?=h(path('/admin/orders/bulk'))?>"><?=csrf_field()?><div class="wp-list-actions"><select name="action" aria-label="Bulk actions"><option value="">Bulk actions</option><?php foreach(['wc-cancelled'=>'Mark cancelled','wc-on-hold'=>'Mark on hold','wc-processing'=>'Mark processing','wc-completed'=>'Mark completed','wc-awaiting-payment'=>'Mark awaiting payment','wc-paid'=>'Mark paid','wc-payment-reminder'=>'Mark payment reminder'] as $value=>$label): ?><option value="<?=h($value)?>"><?=h($label)?></option><?php endforeach; ?></select><button class="secondary">Apply</button><span><?=number_format($count)?> <?=$count===1?'item':'items'?></span></div><div class="wp-list-table-wrap"><table class="wp-list-table"><thead><tr><th><input type="checkbox" aria-label="Select all orders" onclick="document.querySelectorAll('.order-select').forEach(box=>box.checked=this.checked)"></th><th>Order</th><th data-post-col="invoice">Invoice Number</th><th>Date</th><th>Status</th><th data-post-col="billing">Billing</th><th data-post-col="shipping">Ship to</th><th>Total</th><th>Actions</th><th data-post-col="tracking">Shipment Tracking</th><th data-post-col="type">Order Type</th><th data-post-col="origin">Origin</th></tr></thead><tbody><?php foreach($orders as $o): $billing=trim(($o['company']?$o['company'].', ':'').($o['first_name'] ?? '').' '.($o['last_name'] ?? '')); $shipping=trim(($o['shipping_company']?$o['shipping_company'].', ':'').($o['shipping_first'] ?? '').' '.($o['shipping_last'] ?? '')); ?><tr><td><input class="order-select" type="checkbox" name="ids[]" value="<?=h($o['ID'])?>" aria-label="Select order <?=h($o['ID'])?>"></td><td><strong><a href="<?=h(path('/admin/order?id='.$o['ID']))?>">#<?=h($o['ID'])?> <?=h(trim(($o['first_name'] ?? '').' '.($o['last_name'] ?? '')))?></a></strong></td><td data-post-col="invoice"><?=h($o['invoice_number'] ?: '—')?></td><td><?=h($o['post_date'])?></td><td><?=h(ucwords(str_replace(['wc-','-'],['',' '],$o['post_status'])))?></td><td data-post-col="billing"><?=h($billing)?><small><?=h(trim(($o['billing_address'] ?? '').', '.($o['billing_city'] ?? ''),', '))?></small><small><?=h($o['email'])?></small></td><td data-post-col="shipping"><?=h($shipping)?><small><?=h(trim(($o['shipping_address'] ?? '').', '.($o['shipping_city'] ?? ''),', '))?></small></td><td><?=currency($o['total'] ?? 0)?></td><td><a href="<?=h(path('/admin/order?id='.$o['ID']))?>">View</a></td><td data-post-col="tracking"><a href="<?=h(path('/admin/shipment?order='.$o['ID']))?>"><?=$o['tracking']?'Edit tracking':'Add tracking'?></a></td><td data-post-col="type"><?=h($roleNames[$o['order_type']] ?? ($o['order_type'] ?: 'Retail'))?></td><td data-post-col="origin"><?=h($o['origin'] ?: '—')?></td></tr><?php endforeach; if(!$orders): ?><tr><td colspan="12">No orders found.</td></tr><?php endif; ?></tbody></table></div></form><?=admin_pages_nav('/admin/orders',$page,$count,$limit,['q'=>$q,'status'=>$status,'month'=>$month,'role'=>$role,'origin'=>$origin,'per_page'=>$limit])?></div><link rel="stylesheet" href="<?=h(path('/assets/posts-list.css'))?>"><script src="<?=h(path('/assets/posts-list.js'))?>" defer></script><?php });
