function bulk_woo_orders(): never {
    $action=(string)($_POST['action'] ?? '');
    $valid=['wc-cancelled','wc-on-hold','wc-processing','wc-completed','wc-awaiting-payment','wc-paid','wc-payment-reminder','trash','restore'];
    $returnTo=(string)($_POST['return_to'] ?? '/admin/orders');
    if(!preg_match('#^/admin/orders(?:\?[A-Za-z0-9_=&%+.,-]*)?$#',$returnTo))$returnTo='/admin/orders';
    if(!empty($_POST['row_action']) && preg_match('/^quick:(\d+):(wc-processing|wc-completed)$/',(string)$_POST['row_action'],$quick)) {
        $id=(int)$quick[1];$target=$quick[2];
        db()->beginTransaction();
        try {
            $old=row("SELECT post_status FROM wp_posts WHERE ID=? AND post_type='shop_order' FOR UPDATE",[$id]);
            $allowed=$old && (($target==='wc-processing' && in_array($old['post_status'],['wc-pending','wc-on-hold'],true)) || ($target==='wc-completed' && $old['post_status']==='wc-processing'));
            if($allowed){
                exec_sql("UPDATE wp_posts SET post_status=?,post_modified=NOW(),post_modified_gmt=UTC_TIMESTAMP() WHERE ID=? AND post_type='shop_order'",[$target,$id]);
                audit_change('order',$id,'quick_status',['status'=>$old['post_status']],['status'=>$target]);
            }
            db()->commit();
        }catch(Throwable $error){db()->rollBack();throw $error;}
        notice($allowed?'Order #'.$id.' marked '.($target==='wc-processing'?'Processing':'Completed').'.':'This order can no longer use that quick action.');
        redirect($returnTo);
    }
    if(!empty($_POST['row_action']) && preg_match('/^(trash|restore):(\d+)$/',(string)$_POST['row_action'],$match)) { $action=$match[1]; $_POST['ids']=[(int)$match[2]]; }
    if(!in_array($action,$valid,true)) { notice('Select a bulk action.'); redirect('/admin/orders'); }
    $ids=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['ids'] ?? [])),static fn($id)=>$id>0)));
    if(!$ids) { notice('Select at least one order.'); redirect('/admin/orders'); }
    if(count($ids)>100) { notice('Select no more than 100 orders at once.'); redirect('/admin/orders'); }
    db()->beginTransaction();
    try { foreach($ids as $id) { $old=row("SELECT post_status FROM wp_posts WHERE ID=? AND post_type='shop_order' FOR UPDATE",[$id]); if(!$old) continue; if($action==='trash' && $old['post_status']!=='trash') set_wp_meta($id,'_app_previous_order_status',$old['post_status']); $new=$action==='restore'?(wp_meta($id,'_app_previous_order_status') ?: 'wc-processing'):$action; if($action==='restore' && $old['post_status']!=='trash') continue; exec_sql("UPDATE wp_posts SET post_status=?,post_modified=NOW(),post_modified_gmt=UTC_TIMESTAMP() WHERE ID=?",[$new,$id]); audit_change('order',$id,'bulk_status',['status'=>$old['post_status']],['status'=>$new]); } db()->commit(); }
    catch(Throwable $e) { db()->rollBack(); throw $e; }
    notice('Order statuses updated.'); redirect($returnTo);
}

function admin_woo_coupons_wp(): void {
