    $q=trim((string)($_GET['q'] ?? '')); $page=max(1,(int)($_GET['page'] ?? 1)); $limit=(int)($_GET['per_page'] ?? 20); if(!in_array($limit,[10,20,50,100],true)) $limit=20; $offset=($page-1)*$limit;
    $where="p.post_type='shop_coupon'"; $params=[];
