    if($type!=='') { $where.=" AND EXISTS (SELECT 1 FROM wp_postmeta x WHERE x.post_id=p.ID AND x.meta_key='discount_type' AND x.meta_value=?)"; $params[]=$type; }
    if($q!=='') { $where.=' AND (p.post_title LIKE ? OR p.post_excerpt LIKE ?)'; $params[]='%'.$q.'%'; $params[]='%'.$q.'%'; }
    $count=(int)(row("SELECT COUNT(*) n FROM wp_posts p WHERE $where",$params)['n'] ?? 0);
