    $items=rows("SELECT p.ID,p.post_title,p.post_excerpt,p.post_status,".$meta('discount_type')." discount_type,".$meta('coupon_amount')." amount,".$meta('product_ids')." product_ids,".$meta('usage_count')." usage_count,".$meta('usage_limit')." usage_limit,".$meta('date_expires')." date_expires FROM wp_posts p WHERE $where ORDER BY p.ID DESC LIMIT $limit OFFSET $offset",$params);
