      <form class="wp-list-filter" action="<?=h(path('/admin/coupons'))?>"><input type="hidden" name="status" value="<?=h($status)?>"><div class="wp-list-search"><label class="sr-only" for="coupon-search">Search coupons</label><input id="coupon-search" name="q" value="<?=h($q)?>" placeholder="Search coupons"><button class="secondary">Search coupons</button></div><div class="wp-list-actions"><label class="sr-only" for="coupon-type">Coupon type</label><select id="coupon-type" name="type"><option value="">Show all types</option><?php foreach(['percent'=>'Percentage discount','fixed_cart'=>'Fixed cart discount','fixed_product'=>'Fixed product discount'] as $value=>$label): ?><option value="<?=h($value)?>" <?=$type===$value?'selected':''?>><?=h($label)?></option><?php endforeach; ?></select><button class="secondary">Filter</button></div></form>
      <form method="post" action="<?=h(path('/admin/coupons/bulk'))?>"><?=csrf_field()?><div class="wp-list-actions"><select name="action" aria-label="Bulk actions"><option value="">Bulk actions</option><option value="trash">Move to Trash</option><?php if($status==='trash'): ?><option value="restore">Restore</option><option value="delete">Delete Permanently</option><?php endif; ?></select><button class="secondary">Apply</button><span><?=number_format($count)?> <?=$count===1?'item':'items'?></span></div><div class="wp-list-table-wrap"><table class="wp-list-table"><thead><tr><th><input type="checkbox" aria-label="Select all coupons" onclick="document.querySelectorAll('.coupon-select').forEach(box=>box.checked=this.checked)"></th><th>Code</th><th>Coupon type</th><th>Coupon amount</th><th data-post-col="description">Description</th><th data-post-col="product">Product IDs</th><th>Usage / Limit</th><th data-post-col="expiry">Expiry date</th></tr></thead><tbody><?php foreach($items as $c): $label=['percent'=>'Percentage discount','fixed_cart'=>'Fixed cart discount','fixed_product'=>'Fixed product discount'][$c['discount_type']] ?? $c['discount_type']; ?><tr><td><input class="coupon-select" type="checkbox" name="ids[]" value="<?=h($c['ID'])?>" aria-label="Select <?=h($c['post_title'])?>"></td><td><strong><a href="<?=h(path('/admin/coupon?id='.$c['ID']))?>"><?=h($c['post_title'])?></a></strong><div class="row-actions"><a href="<?=h(path('/admin/coupon?id='.$c['ID']))?>">Edit</a><?php if($c['post_status']!=='trash'): ?><button name="row_action" value="trash:<?=h($c['ID'])?>">Trash</button><?php else: ?><button name="row_action" value="restore:<?=h($c['ID'])?>">Restore</button><button name="row_action" value="delete:<?=h($c['ID'])?>" onclick="return confirm('Permanently delete this coupon?')">Delete Permanently</button><?php endif; ?></div></td><td><?=h($label)?></td><td><?=h($c['amount'] ?? '0')?></td><td data-post-col="description"><?=h($c['post_excerpt'] ?: '–')?></td><td data-post-col="product"><?=h($c['product_ids'] ?: '–')?></td><td><?=h($c['usage_count'] ?? '0')?> / <?=h($c['usage_limit'] ?: '∞')?></td><td data-post-col="expiry"><?=h($c['date_expires'] ?: '–')?></td></tr><?php endforeach; if(!$items): ?><tr><td colspan="8">No coupons found.</td></tr><?php endif; ?></tbody></table></div></form><?=admin_pages_nav('/admin/coupons',$page,$count,$limit,['q'=>$q,'status'=>$status,'type'=>$type,'per_page'=>$limit])?></div><link rel="stylesheet" href="<?=h(path('/assets/posts-list.css'))?>"><script src="<?=h(path('/assets/posts-list.js'))?>" defer></script><?php });
}

function bulk_woo_coupons(): never {
    $action=(string)($_POST['action'] ?? ''); $ids=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['ids'] ?? [])),static fn($id)=>$id>0)));
    if(!empty($_POST['row_action']) && preg_match('/^(trash|restore|delete):(\d+)$/',(string)$_POST['row_action'],$match)) { $action=$match[1]; $ids=[(int)$match[2]]; }
    if(!in_array($action,['trash','restore','delete'],true) || !$ids || count($ids)>100) { notice('Select coupons and an action.'); redirect('/admin/coupons'); }
    db()->beginTransaction();
    try { foreach($ids as $id) { $old=row("SELECT post_status FROM wp_posts WHERE ID=? AND post_type='shop_coupon' FOR UPDATE",[$id]); if(!$old) continue; if($action==='delete') { if($old['post_status']!=='trash') continue; exec_sql('DELETE FROM wp_postmeta WHERE post_id=?',[$id]); exec_sql("DELETE FROM wp_posts WHERE ID=? AND post_type='shop_coupon'",[$id]); } else { $new=$action==='trash'?'trash':'publish'; exec_sql("UPDATE wp_posts SET post_status=?,post_modified=NOW() WHERE ID=? AND post_type='shop_coupon'",[$new,$id]); } audit_change('coupon',$id,$action,['status'=>$old['post_status']],[]); } db()->commit(); }
    catch(Throwable $e) { db()->rollBack(); throw $e; }
    notice('Coupon action completed.'); redirect('/admin/coupons');
}
